C0028.falsifier_code:
"""Falsifier C0028 -- BUILD_BOT_TEST_BENCH_FIX_SPEC.md

Claim under test: the Scope block names three patchable files, while Sec.1C
imposes an eight-key contract on the `benchmark_meta` envelope. That envelope
has a SECOND writer in the same package -- bench/run_experiment.py, which
imports its harness entry points from the in-Scope run_benchmark.py -- and
Scope does not list it. It omits mandated keys, so Sec.1C is unenforceable
as scoped: the only writer the spec may patch is already compliant, and the
non-compliant one is off-limits.

Both halves of the contract are recomputed from the document text; the
writer census is recomputed from the repo by AST.
"""
import ast
import pathlib
import re

DOC = pathlib.Path("bench/BUILD_BOT_TEST_BENCH_FIX_SPEC.md")
BENCH = DOC.parent
text = DOC.read_text(encoding="utf-8")

# --- 1. the Scope block's patchable-file list, from the document ----------
scope_m = re.search(r"^## Scope\n(.*?)(?=^## )", text, re.S | re.M)
assert scope_m, "Scope block not found"
scope_files = set(re.findall(r"^-\s*`([^`]+)`", scope_m.group(1), re.M))
assert scope_files, "no files parsed from Scope block"

# --- 2. the Sec.1C mandated envelope keys, from the document --------------
c_m = re.search(
    r"`benchmark_meta` should include at least:\n((?:^-\s*`.*\n?)+)", text, re.M
)
assert c_m, "Sec.1C benchmark_meta key list not found"
mandated = {
    km.group(1)
    for line in c_m.group(1).splitlines()
    if (km := re.match(r"^-\s*`([^`]+)`", line.strip()))
}
assert len(mandated) == 8, f"expected 8 mandated keys, parsed {sorted(mandated)}"


def literal_keys(node, tree):
    """String keys of a dict literal, resolving one level of Name alias."""
    if isinstance(node, ast.Name):
        best = None
        for n in ast.walk(tree):
            if isinstance(n, ast.Assign):
                targets = n.targets
            elif isinstance(n, ast.AnnAssign):
                targets = [n.target]
            else:
                continue
            if not isinstance(n.value, ast.Dict):
                continue
            if any(isinstance(t, ast.Name) and t.id == node.id for t in targets):
                if n.lineno <= node.lineno and (best is None or n.lineno > best.lineno):
                    best = n
        node = best.value if best is not None else None
    if not isinstance(node, ast.Dict):
        return None
    return {k.value for k in node.keys
            if isinstance(k, ast.Constant) and isinstance(k.value, str)}


# --- 3. census of every benchmark_meta writer in the bench tree -----------
writers = []
for py in sorted(BENCH.rglob("*.py")):
    try:
        src = py.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        continue
    if "benchmark_meta" not in src:
        continue
    try:
        tree = ast.parse(src)
    except SyntaxError:
        continue
    for n in ast.walk(tree):
        if not isinstance(n, ast.Dict):
            continue
        for k, v in zip(n.keys, n.values):
            if not (isinstance(k, ast.Constant) and k.value == "benchmark_meta"):
                continue
            keys = literal_keys(v, tree)
            if keys is None:          # not a resolvable literal -- can't judge
                continue
            writers.append((py.relative_to(BENCH.parent).as_posix(),
                            k.lineno, mandated - keys))

# Guards: the census must be non-vacuous and the contract satisfiable,
# otherwise a quiet exit would prove nothing.
assert len(writers) >= 2, f"expected >=2 resolvable benchmark_meta writers, got {writers}"
assert any(not miss and rel in scope_files for rel, _, miss in writers), (
    "no in-Scope writer is Sec.1C-complete; this falsifier is not measuring "
    "the scope asymmetry it claims to"
)

offenders = [(r, l, sorted(m)) for r, l, m in writers if m and r not in scope_files]

if offenders:
    print("Scope block names:", sorted(scope_files))
    print("Sec.1C mandates  :", sorted(mandated))
    for rel, line, missing in writers:
        tag = "in-Scope" if rel in scope_files else "OUT-OF-SCOPE"
        print(f"  {tag:12} {rel}:{line} missing={sorted(missing) or 'none'}")
    raise AssertionError(
        "FALSIFIED: Sec.1C imposes an 8-key benchmark_meta contract, but "
        f"{len(offenders)} writer(s) of that envelope lie outside the Scope "
        "block and violate it -- the contract cannot be enforced as scoped: "
        + "; ".join(f"{r}:{l} omits {m}" for r, l, m in offenders)
    )
print("clean: every benchmark_meta writer is either in Scope or Sec.1C-complete")
